css:
.destmaker-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #e8f4f8 0%, #d1ecf1 50%, #e2e6ea 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.destmaker-sim-container .destmaker-sim-header {
    background: linear-gradient(135deg, #0077b6 0%, #023e8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 25px;
    box-shadow: 0 8px 20px rgba(2,62,138,0.25);
    text-align: center;
}

.destmaker-sim-container .destmaker-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.destmaker-sim-container .destmaker-sim-header p {
    margin: 0;
    opacity: 0.9;
    font-size: 1.05rem;
}

.destmaker-sim-container .destmaker-sim-period-counter {
    text-align: center;
    font-size: 1.15rem;
    color: #495057;
    margin-bottom: 20px;
    font-weight: 600;
}

.destmaker-sim-container .destmaker-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
    gap: 15px;
    margin-bottom: 25px;
}

.destmaker-sim-container .destmaker-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 20px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    text-align: center;
    transition: transform 0.3s ease;
    border-top: 4px solid #ccc;
}

.destmaker-sim-container .destmaker-sim-status-card:hover {
    transform: translateY(-4px);
}

.destmaker-sim-container .destmaker-card-budget { border-top-color: #0077b6; }
.destmaker-sim-container .destmaker-card-visitors { border-top-color: #00b4d8; }
.destmaker-sim-container .destmaker-card-revenue { border-top-color: #2d6a4f; }
.destmaker-sim-container .destmaker-card-nps { border-top-color: #7b2cbf; }
.destmaker-sim-container .destmaker-card-sustain { border-top-color: #38b000; }
.destmaker-sim-container .destmaker-card-community { border-top-color: #e85d04; }

.destmaker-sim-container .destmaker-sim-label {
    color: #6c757d;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.destmaker-sim-container .destmaker-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #212529;
}

.destmaker-sim-container .destmaker-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #0077b6;
}

.destmaker-sim-container .destmaker-sim-briefing-icon {
    font-size: 2rem;
    margin-bottom: 6px;
}

.destmaker-sim-container .destmaker-sim-briefing-title {
    margin: 0 0 8px 0;
    font-size: 1.15rem;
    font-weight: 700;
    color: #023e8a;
}

.destmaker-sim-container .destmaker-sim-briefing-text {
    margin: 0;
    color: #495057;
    line-height: 1.6;
}

.destmaker-sim-container .destmaker-sim-event {
    background: linear-gradient(135deg, #fff3cd 0%, #ffeeba 100%);
    border-radius: 14px;
    padding: 18px 22px;
    margin-bottom: 20px;
    border-left: 5px solid #ffc107;
    box-shadow: 0 3px 10px rgba(0,0,0,0.06);
}

.destmaker-sim-container .destmaker-sim-event h4 {
    margin: 0 0 8px 0;
    color: #856404;
    font-size: 1rem;
}

.destmaker-sim-container .destmaker-sim-event p {
    margin: 0;
    color: #664d03;
    line-height: 1.5;
}

.destmaker-sim-container .destmaker-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 26px;
    margin-bottom: 25px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.destmaker-sim-container .destmaker-sim-controls h3 {
    color: #023e8a;
    font-size: 1.15rem;
    margin-bottom: 6px;
}

.destmaker-sim-container .destmaker-sim-hint {
    color: #6c757d;
    font-size: 0.9rem;
    margin-bottom: 18px;
    line-height: 1.5;
}

.destmaker-sim-container .destmaker-sim-input-group {
    margin-bottom: 16px;
}

.destmaker-sim-container .destmaker-sim-input-group label {
    display: block;
    font-weight: 600;
    color: #343a40;
    margin-bottom: 4px;
    font-size: 0.92rem;
}

.destmaker-sim-container .destmaker-sim-input-group .form-control {
    border-radius: 8px;
    border: 1.5px solid #ced4da;
    padding: 8px 12px;
    font-size: 0.95rem;
}

.destmaker-sim-container .destmaker-sim-input-group .form-control:focus {
    border-color: #0077b6;
    box-shadow: 0 0 0 3px rgba(0,119,182,0.15);
}

.destmaker-sim-container .destmaker-sim-input-hint {
    display: block;
    color: #868e96;
    font-size: 0.8rem;
    margin-top: 3px;
}

.destmaker-sim-container .destmaker-sim-range-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 4px;
    font-size: 0.82rem;
    color: #6c757d;
}

.destmaker-sim-container .destmaker-sim-range-row strong {
    font-size: 1.1rem;
    color: #023e8a;
}

.destmaker-sim-container .destmaker-sim-alloc-bar {
    background: #e9ecef;
    border-radius: 8px;
    padding: 10px 14px;
    margin-top: 12px;
    font-size: 0.9rem;
    color: #495057;
}

.destmaker-sim-container .destmaker-sim-alloc-bar strong {
    color: #0077b6;
}

.destmaker-sim-container .destmaker-sim-submit {
    margin-top: 18px;
    border-radius: 10px;
    padding: 12px 32px;
    font-weight: 600;
    font-size: 1.05rem;
    background: linear-gradient(135deg, #0077b6 0%, #023e8a 100%);
    border: none;
    box-shadow: 0 4px 12px rgba(0,119,182,0.3);
}

.destmaker-sim-container .destmaker-sim-submit:hover {
    background: linear-gradient(135deg, #023e8a 0%, #001d3d 100%);
}

.destmaker-sim-container .destmaker-sim-undo {
    margin-top: 10px;
    margin-left: 10px;
    border-radius: 8px;
}

.destmaker-sim-container .destmaker-sim-history {
    margin-bottom: 25px;
}

.destmaker-sim-container .destmaker-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 30px;
}

.destmaker-sim-container .destmaker-sim-chart-box {
    background: white;
    border-radius: 14px;
    padding: 18px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 280px;
    position: relative;
}

@media (max-width: 768px) {
    .destmaker-sim-container .destmaker-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .destmaker-sim-container .destmaker-sim-charts {
        grid-template-columns: 1fr;
    }
    .destmaker-sim-container .destmaker-sim-value {
        font-size: 1.3rem;
    }
}

@media (max-width: 480px) {
    .destmaker-sim-container .destmaker-sim-status-cards {
        grid-template-columns: 1fr 1fr;
        gap: 10px;
    }
    .destmaker-sim-container .destmaker-sim-header h1 {
        font-size: 1.3rem;
    }
}

