        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastEntry = history[history.length - 1];
            var ds = lastEntry.domainState || {};
            var cumRev = ds.cumulativeRevenue || 0;
            var nps = ds.nps || 0;
            var sust = ds.sustainabilityIndex || 0;
            var comm = ds.communityScore || 0;

            var revScore = Math.min(100, (cumRev / 1500) * 100);
            var overall = Math.round((revScore * 0.25) + (nps * 0.25) + (sust * 0.25) + (comm * 0.25));

            var archetype = 'Developing Destination';
            if (revScore >= 60 && nps >= 55 && sust >= 60 && comm >= 60) {
                archetype = 'Sustainable Growth Champion';
            } else if (revScore >= 70 && (sust < 50 || comm < 50)) {
                archetype = 'Growth at Cost';
            } else if ((sust >= 65 || comm >= 65) && revScore < 50) {
                archetype = 'Niche Player';
            } else if (overall >= 55) {
                archetype = 'Balanced Leader';
            }

            var insights = [];
            if (cumRev >= 1500) insights.push('Revenue target of $1.5B achieved — strong commercial performance.');
            if (cumRev < 1200) insights.push('Revenue fell short of the $1.5B target. Marketing alignment or volume may need adjustment.');
            if (nps >= 65) insights.push('High visitor satisfaction indicates strong experience design and brand alignment.');
            if (nps < 40) insights.push('Low NPS suggests overcrowding, brand mismatch, or infrastructure gaps.');
            if (sust >= 70) insights.push('Strong sustainability credentials position Valdesol for long-term resilience.');
            if (sust < 40) insights.push('Sustainability gap may expose Valdesol to regulatory and reputational risk.');
            if (comm >= 70) insights.push('Community advocacy strengthens social license and drives word-of-mouth demand.');
            if (comm < 40) insights.push('Low community benefit risks backlash, protest, and negative publicity.');

            return {
                cumulativeRevenue: cumRev,
                finalNPS: nps,
                sustainabilityIndex: sust,
                communityScore: comm,
                overallScore: overall,
                archetype: archetype,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            var period = state.currentPeriod;

            if (period === 1) {
                if (ds.nps < 40) return window.mySimulation.t('hint_nps_low');
                if (ds.visitors < 1.0) return window.mySimulation.t('hint_visitors_low');
            }
            if (period === 2) {
                if (ds.commercialization >= 8) return window.mySimulation.t('hint_over_commercial');
                if (ds.communityScore < 40) return window.mySimulation.t('hint_community_risk');
            }
            if (period === 3) {
                if (ds.sustainabilityIndex < 40) return window.mySimulation.t('hint_sustain_low');
            }
            return null;
        }

